const mongoose = require('mongoose');

async function connectDB() {
  const uri = process.env.MONGO_URI || 'mongodb://127.0.0.1:27017/akole_ccms';
  try {
    await mongoose.connect(uri);
    // Generated by GitHub Copilot - Oct-17-2026
    console.log('[DB] MongoDB connected.');
  } catch (err) {
    // Generated by GitHub Copilot - Oct-17-2026
    console.error('[DB] MongoDB connection failed. Check MONGO_URI, credentials, Atlas network access, and TLS settings.');
    process.exit(1);
  }
}

module.exports = connectDB;
